//! Hostile-input corpus smoke suite — queue row 156, sub-item A, kill 1.
//!
//! Every file under `tests/corpus/` (one subdir per format; see
//! `tests/corpus/README.md`, regenerated by `tests/corpus/gen.py`) is
//! hostile input. This always-on suite runs **every corpus file through
//! every pub importer entry point** enumerated from `lib.rs`:
//!
//! - [`umber_mesh::load`] (the extension dispatcher, carries its own
//!   `catch_unwind` boundary → [`ImportError::Panicked`])
//! - [`umber_mesh::load_obj`]
//! - [`umber_mesh::gltf::load_gltf`] (`.gltf`/`.glb`)
//! - [`umber_mesh::fbx::load_fbx`]
//! - [`umber_mesh::usd::load_usda`] (`.usda`/text `.usd`; the byte-level
//!   core is `usd::parse_usda_bytes`, reached through this entry)
//! - [`umber_mesh::usdc::load_usdc`] (`.usdc`, reads the bytes itself)
//! - [`umber_mesh::usdc::load_usdz`] (`.usdz` package, zip via openusd)
//!
//! Each direct entry call is wrapped in [`std::panic::catch_unwind`]: a
//! panic in an importer (including a dependency) becomes a NAMED test
//! failure, never a silent pass and never a killed test process. Every
//! case must return a typed `Err` — never a panic, never a silent `Ok`.
//!
//! The long mutational lane over these seeds is `hostile_fuzz.rs`
//! (`#[ignore]`d); any finding it surfaces lands here as a new corpus
//! file so this suite covers it permanently.

use std::cell::RefCell;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::path::{Path, PathBuf};

use umber_mesh::{ImportError, MeshData};

thread_local! {
    static LAST_PANIC: RefCell<String> = const { RefCell::new(String::new()) };
}

/// Install a hook that records the panic site instead of printing it, so
/// a caught importer panic stays a named failure, not stderr noise.
fn install_quiet_hook() {
    use std::sync::Once;
    static ONCE: Once = Once::new();
    ONCE.call_once(|| {
        let default = std::panic::take_hook();
        std::panic::set_hook(Box::new(move |info| {
            let site = format!("{info}");
            LAST_PANIC.with(|p| *p.borrow_mut() = site);
            // Keep the default output too: a panic is a bug, the noise is
            // the point — the catch_unwind below turns it into the named
            // failure.
            default(info);
        }));
    });
}

/// One importer entry point: name + the pub loader fn.
type Entry = (&'static str, fn(&Path) -> Result<MeshData, ImportError>);

/// The pub importer entry points, enumerated from `lib.rs` and the pub
/// format modules. `load` is the dispatcher; the rest are called
/// directly (their own panics are caught per case below).
fn importer_entries() -> Vec<Entry> {
    vec![
        ("load", umber_mesh::load),
        ("load_obj", umber_mesh::load_obj),
        ("gltf::load_gltf", umber_mesh::gltf::load_gltf),
        ("fbx::load_fbx", umber_mesh::fbx::load_fbx),
        ("usd::load_usda", umber_mesh::usd::load_usda),
        ("usdc::load_usdc", umber_mesh::usdc::load_usdc),
        ("usdc::load_usdz", umber_mesh::usdc::load_usdz),
    ]
}

/// The corpus format subdirs; every regular file inside is a sample.
const CORPUS_SUBDIRS: [&str; 5] = ["fbx", "gltf", "usda", "usdc", "usdz"];

fn corpus_files() -> Vec<PathBuf> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/corpus");
    let mut files = Vec::new();
    for sub in CORPUS_SUBDIRS {
        let dir = root.join(sub);
        let mut entries: Vec<PathBuf> = std::fs::read_dir(&dir)
            .unwrap_or_else(|e| panic!("corpus dir {dir:?} must exist: {e}"))
            .map(|e| e.expect("corpus entry readable").path())
            .filter(|p| p.is_file())
            .collect();
        entries.sort();
        files.extend(entries);
    }
    files
}

/// Run one entry over one file; a panic is returned as a named failure.
fn run_case(
    f: fn(&Path) -> Result<MeshData, ImportError>,
    path: &Path,
) -> Result<Result<MeshData, ImportError>, String> {
    install_quiet_hook();
    catch_unwind(AssertUnwindSafe(|| f(path))).map_err(|payload| {
        let msg = payload
            .downcast_ref::<String>()
            .cloned()
            .or_else(|| payload.downcast_ref::<&str>().map(|s| (*s).to_string()))
            .unwrap_or_else(|| "<non-string panic payload>".to_string());
        let site = LAST_PANIC.with(|p| std::mem::take(&mut *p.borrow_mut()));
        let at = site
            .lines()
            .find(|l| {
                l.contains("umber_mesh::")
                    || l.contains("openusd::")
                    || l.contains("ufbx::")
                    || l.contains("gltf::")
                    || l.contains("tobj::")
            })
            .unwrap_or("?")
            .trim()
            .to_string();
        format!("PANIC: {msg} at {at}")
    })
}

#[test]
fn corpus_is_present_and_nonempty() {
    let files = corpus_files();
    assert!(
        files.len() >= 33,
        "expected the 33 hostile samples under tests/corpus/, found {}",
        files.len()
    );
}

#[test]
fn every_corpus_file_is_a_typed_err_through_every_importer_entry() {
    let files = corpus_files();
    let entries = importer_entries();
    let mut failures: Vec<String> = Vec::new();
    let mut cases = 0usize;
    for path in &files {
        let rel = path
            .strip_prefix(Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/corpus"))
            .unwrap()
            .display();
        for (name, f) in &entries {
            cases += 1;
            match run_case(*f, path) {
                Ok(Ok(mesh)) => failures.push(format!(
                    "{rel} x {name}: hostile input ACCEPTED (Ok: {} verts, {} indices)",
                    mesh.vertex_count(),
                    mesh.triangle_count()
                )),
                Ok(Err(_)) => {} // the contract: a typed Err
                Err(panic) => failures.push(format!("{rel} x {name}: {panic}")),
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{cases} corpus cases, {} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
